,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT                                                         ',
'      company_name,                                                         ',
'      ticker,',
'      ''$'' || TO_CHAR(current_price, ''FM999,990.00'')       AS     ',
'  stock_price,          ',
'      TO_CHAR(ABS(pct_change), ''FM990.00'') || ''%''         AS',
'  stock_change,',
'      CASE',
'          WHEN pct_change > 0  THEN ''success''',
'          WHEN pct_change < 0  THEN ''danger''',
'      END                                                  AS',
'  state,',
'      CASE',
'          WHEN pct_change > 0  THEN ''fa-arrow-up''',
'          WHEN pct_change < 0  THEN ''fa-arrow-down''',
'      END                                                  AS',
'  icon_class',
'  FROM (',
'      SELECT ''Apple''     AS company_name, ''AAPL''  AS ticker,',
'  189.45 AS current_price,  2.34 AS pct_change FROM dual UNION',
'  ALL',
'      SELECT ''Microsoft'' AS company_name, ''MSFT''  AS ticker,',
'  415.80 AS current_price, -0.87 AS pct_change FROM dual UNION',
'  ALL',
'      SELECT ''Google''    AS company_name, ''GOOGL'' AS ticker,',
'  175.20 AS current_price,  1.12 AS pct_change FROM dual UNION',
'  ALL',
'      SELECT ''Amazon''    AS company_name, ''AMZN''  AS ticker,',
'  198.60 AS current_price, -3.45 AS pct_change FROM dual UNION',
'  ALL',
'      SELECT ''Tesla''     AS company_name, ''TSLA''  AS ticker,',
'  245.10 AS current_price,  1.00 AS pct_change FROM dual',
'  )'))
,p_template_component_type=>'REPORT'
,p_lazy_loading=>false
,p_plug_source_type=>'TMPL_THEME_42$METRIC_CARD'
,p_plug_query_num_rows=>50
,p_plug_query_num_rows_type=>'SET'
,p_show_total_row_count=>false
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'AVATAR_ALIGNMENT', 't-MetricCard-body--avatarAlignmentCenter',
  'AVATAR_ICON', 'fa-line-chart',
  'AVATAR_POSITION', 't-MetricCard-body--avatarPositionInline',
  'AVATAR_SHAPE', 't-Avatar--square',
  'AVATAR_STYLE', 't-MetricCard-avatar--subtle',
  'AVATAR_TYPE', 'icon',
  'BADGE_ICON', '&ICON_CLASS.',
