'fa-badge-percent',
'fa-biohazard',
'fa-bug-slash',
'fa-file-brackets',
'fa-file-csv',
'fa-file-json',
'fa-file-medical',
'fa-file-prescription',
'fa-file-signature',
'fa-flag-pennant',
'fa-flag-pennant-o',
'fa-flag-swallowtail',
'fa-flag-swallowtail-o',
'fa-frown',
'fa-heat-map',
'fa-line-map',
'fa-location',
'fa-location-arrow-solid',
'fa-location-circle',
'fa-location-circle-solid',
'fa-location-slash',
'fa-map-marker-camera',
'fa-map-marker-camera-o',
'fa-map-marker-check',
'fa-map-marker-check-o',
'fa-map-marker-face-frown',
'fa-map-marker-face-frown-o',
'fa-map-marker-face-meh',
'fa-map-marker-face-meh-o',
